"""Exhaustive verification of the generalized multinomial convolution identity."""
from itertools import product
from math import comb

def lhs(m: int, a: int, d: int) -> int:
    total = 0
    for tup in product(range(d + 1), repeat=m):
        if sum(tup) == d:
            prod = 1
            for x in tup:
                prod *= comb(a + x, a)
            total += prod
    return total

def rhs(m: int, a: int, d: int) -> int:
    return comb(m * a + d + m - 1, d)

if __name__ == "__main__":
    for m in range(1, 5):
        for a in range(0, 4):
            for d in range(0, 6):
                assert lhs(m, a, d) == rhs(m, a, d), (m, a, d)
    print("All checks passed: sum prod C(a+i_j,a) = C(m*a+d+m-1, d)")

"""Two-factor negative binomial convolution (the base engine)."""
from math import comb

def conv_lhs(p: int, q: int, d: int) -> int:
    return sum(comb(p + i, p) * comb(q + (d - i), q) for i in range(d + 1))

def conv_rhs(p: int, q: int, d: int) -> int:
    return comb(p + q + 1 + d, d)

if __name__ == "__main__":
    for p in range(0, 5):
        for q in range(0, 5):
            for d in range(0, 8):
                assert conv_lhs(p, q, d) == conv_rhs(p, q, d), (p, q, d)
    print("Verified: sum_{i+j=d} C(p+i,p) C(q+j,q) = C(p+q+1+d, d)")

"""Generating-function check via polynomial (power-series) multiplication.

The identity is the additivity of exponents: (1-x)^{-(a+1)} raised to the m-th
power is (1-x)^{-m(a+1)}. We verify the coefficient of x^d numerically by
truncated power-series multiplication and compare with C(m*a+d+m-1, d).
"""
from math import comb
from typing import List

def negbinom_series(a: int, N: int) -> List[int]:
    """Coefficients [C(a+0,a), ..., C(a+N,a)] of (1-x)^{-(a+1)} up to x^N."""
    return [comb(a + i, a) for i in range(N + 1)]

def poly_mul(f: List[int], g: List[int], N: int) -> List[int]:
    out = [0] * (N + 1)
    for i, fi in enumerate(f):
        if i > N:
            break
        for j, gj in enumerate(g):
            if i + j > N:
                break
            out[i + j] += fi * gj
    return out

def series_power(a: int, m: int, N: int) -> List[int]:
    result = [1] + [0] * N
    base = negbinom_series(a, N)
    for _ in range(m):
        result = poly_mul(result, base, N)
    return result

if __name__ == "__main__":
    N = 10
    for m in range(1, 5):
        for a in range(0, 4):
            coeffs = series_power(a, m, N)
            for d in range(N + 1):
                assert coeffs[d] == comb(m * a + d + m - 1, d), (m, a, d)
    print("Coefficient extraction matches C(m*a+d+m-1, d) for all tested (m,a,d).")

"""Stars-and-bars specialization (a = 0) recovering weak-composition counts."""
from itertools import product
from math import comb

def count_compositions(m: int, d: int) -> int:
    return sum(1 for t in product(range(d + 1), repeat=m) if sum(t) == d)

if __name__ == "__main__":
    for m in range(1, 6):
        for d in range(0, 7):
            assert count_compositions(m, d) == comb(d + m - 1, d), (m, d)
            print(f"m={m} d={d}: {count_compositions(m, d)} = C({d+m-1},{d})")
    print("Verified: number of m-tuples summing to d equals C(d+m-1, d).")

