from itertools import combinations
from typing import Iterator, Tuple

def weak_compositions(m: int, d: int) -> Iterator[Tuple[int, ...]]:
    """Enumerate all ordered m-tuples of non-negative integers summing to d.

    Uses the stars-and-bars bijection: place m-1 dividers among d+m-1 slots;
    the gaps between consecutive dividers give the parts. Yields exactly
    C(d+m-1, d) tuples. Time O(C(d+m-1, d) * m), space O(m) per tuple.
    """
    if m == 0:
        if d == 0:
            yield ()
        return
    for divs in combinations(range(d + m - 1), m - 1):
        parts = []
        prev = -1
        for pos in divs:
            parts.append(pos - prev - 1)
            prev = pos
        parts.append((d + m - 1) - prev - 1)
        yield tuple(parts)

